import React from "react";
import { Link } from "react-router-dom";
import logo from "../../images/logo.png";
import homeIcon from "../../icons/menu/home.png";
import searchIcon from "../../icons/menu/search.png";
import soulsIconActive from "../../icons/menu/souls-active.png";
import walletIconActive from "../../icons/menu/wallet-active.png";
import soulsIconInactive from "../../icons/menu/souls-inactive.png";
import walletIconInactive from "../../icons/menu/wallet-inactive.png";
import settingsIcon from "../../icons/menu/settings.png";

const Sidebar = ({ activeMenu }) => {
  const state = true;
  const menus = [
    { id: 1, href: "/", title: "Home", icon: homeIcon },
    { id: 2, href: "/trade", title: "Trade", icon: searchIcon },
    { id: 3, href: "/wallet", title: "Wallet", icon: soulsIconInactive },
    { id: 4, href: "/price", title: "Price", icon: walletIconInactive },
    { id: 5, href: "/settings-profile", title: "Settings", icon: settingsIcon }
  ];
  return (
    <div className="sidebar">
      
      <div className="menu">
        <ul>
          {menus.map((item) => (
            <li key={item.id} className={activeMenu == item.id ? "active" : ""}>
              <Link
                to={item.href}
                title={item.title}
                className={activeMenu == item.id ? "active" : ""}
              >
                <span>
                  <img src={item.icon}></img>
                  {/* <i className={item.icon}></i> */}
                </span>
              </Link>
            </li>
          ))}

          {/* <li className="logout">
            <Link to={"/signin"} title="Signout">
              <span>
                <i className="icofont-power"></i>
              </span>
            </Link>
          </li> */}
        </ul>

        {/* <p className="copyright">
          &#169; <Link to={"/#"}>Qcash</Link>
        </p> */}
      </div>
    </div>
  );
};

export default Sidebar;
